var tipuesearch = {"pages": [{'title': 'About', 'text': '國立虎尾科技大學機械設計工程系 \n National Formosa University \n Department of Mechanical Design Engineering \n cp2024 計算機程式 \n 課程教材: \n Learn Python with Jupyter  ( site ,  ebook ) \n 教育版帳號\xa0microsoftonline 登入點:\xa0 https://login.microsoftonline.com/ \n Teams 線上教學: \n 以 "學號@nfu.edu.tw" 登入  https://login.microsoftonline.com/  Office 365\xa0 \n Teams 團隊代碼: fqpabi8 \n 個人倉儲: https://github.com/mdecp2024/hw-41323211 \n 個人網站: https://mdecp2024.github.io/hw-41323211 \n 其他資訊: \n cd2023_pj3ag4_zmq_football_4.7.7z \n cd2024_2b_g6_steel_ball_platform_nxopen_copsim.7z', 'tags': '', 'url': 'About.html'}, {'title': 'Attendance', 'text': '出席 (10%) - 自行舉證評分 \n 自行利用 Github commits 提交記錄評分. \n', 'tags': '', 'url': 'Attendance.html'}, {'title': 'HW 1', 'text': '主題: 基於瀏覽器的分散式版次管理與整合程式開發環境 (10%) \n USB 隨身碟: \n 下載  python_2025_lite.7z  (428 MB, 解開壓縮後約 1.5 GB) \n Jupyter \n What are Github and Codespaces? \n Hello World - GitHub Docs \n 利用包含學號的字串作為帳號, 申請免費使用 Github. \n Python 課程教材:  https://www.learnpythonwithjupyter.com/  - PART 1 \n \n PART 1: Creating the basics 資料整理 (10%) \n 啟動可攜程式系統後, 在命令列中: \n y:\\>cd notebook \n y:\\notebook>jupyter lab --collaborative \n 進入  01_string_input_print.ipynb  練習如何修改 PART1 notebook 後存檔, 上傳至作業倉儲中的 downloads 目錄後, 透過  https://nbviewer.org/  將已經提交的  01_string_input_print.ipynb , 嵌入下列網頁中. \n \n 上列 iframe 標註的 html 語法: \n <iframe width="600" height="400" src="https://nbviewer.org/urls/mde.tw/cp2024_hw/downloads/01_string_input_print.ipynb"></iframe> \n 完成上述流程整理後, 請將 HW1 自評分數輸入 cp2024 自評表單中. \n', 'tags': '', 'url': 'HW 1.html'}, {'title': 'w10', 'text': '11/13 \n \n \n \n', 'tags': '', 'url': 'w10.html'}, {'title': 'w11_hw', 'text': '算行數 \n n = 11 # 總共的行數 space = \'_\' center = n//2 #print(center) \n for y in range(n):  for x in range(n):  print("(", x, ", ", y, ")", sep="") \n 用筆畫方格子 \n from browser import html\n\nfrom browser import document as doc\n \n# 利用 html 建立 canvas 超文件物件\n\ncanvas = html.CANVAS(width=400, height=400)\n\nbrython_div = doc["brython_div1"]\n\nbrython_div <= canvas\n \n#每一個的pixcel數\n\ngs = 20\n \n#gs"tc = canvas width and height\n \nctx = canvas.getContext("2d")\n\nwidth = 11\n\nheight = 11\n \n \nfor i in range(width):\n\n     for j in range(height):\n\n         #dRect(i*gs,j*gs,gs,gs,1,"red"\n\n          ctx.lineWidth = 1\n\n          ctx.strokeStyle = \'red\'\n\n          ctx.beginPath();\n\n          ctx.rect(i*gs,j*gs,gs,gs)\n\n          ctx.stroke();\n  \n', 'tags': '', 'url': 'w11_hw.html'}, {'title': 'w13_hw', 'text': '雙正方形 \n from browser import html #導入html函式庫  from browser import document as doc #導入document程式庫並在程式中命名(簡寫)為doc \n \xa0 \n # 利用 html 建立 canvas 超文件物件  canvas = html.CANVAS(width = 400,height = 400) #將變數canvas指定為html.CANVAS(width = 400,height = 400)\xa0  #意思是建立*(準備)一個400*400的空間(畫布)  brython_div = doc["brython_div1"] #將變數brython_div指定為doc["brython_div1"]  brython_div <= canvas #將canve指定為子元素加入倒brython_div中 \n \xa0 \n # 每一格的 pixel 數  gs = 200 \n \xa0 \n # gs*tc = canvas width and height \n \xa0 \n ctx = canvas.getContext("2d") #將ctx指定(簡寫)為canvas.getContext("2d") (獲取畫布（canvas）的 2D 繪圖上下文 (context))  width=1 #方形的寬  height=1 #方形的高 \n \xa0 \n #第一個方形  for i in range(width):\xa0  \xa0\xa0\xa0 for j in range(height):  \xa0\xa0\xa0\xa0 #dRect(i*gs, j*gs, gs, gs, 1, "lightgrey")  \xa0\xa0\xa0\xa0 ctx.lineWidth=1  \xa0\xa0\xa0\xa0 ctx.strokeStyle=\'red\'  \xa0\xa0\xa0\xa0 ctx.beginPath();  \xa0\xa0\xa0\xa0 ctx.rect(i*gs,j*gs,gs,gs)  \xa0\xa0\xa0\xa0 ctx.stroke();  #第二個偏移的方形  for i in range(width):\xa0  \xa0\xa0\xa0 for j in range(height):  \xa0\xa0\xa0\xa0 #dRect(i*gs, j*gs, gs, gs, 1, "lightgrey")  \xa0\xa0\xa0\xa0 ctx.lineWidth=1  \xa0\xa0\xa0\xa0 ctx.strokeStyle=\'red\'  \xa0\xa0\xa0\xa0 ctx.beginPath();  \xa0\xa0\xa0\xa0 ctx.rect(i*gs+100,j*gs+100,gs,gs)\xa0\xa0\xa0\xa0\xa0 #gs+100代表往右下偏移100像素  \xa0\xa0\xa0\xa0 ctx.stroke(); \n 圓被兩個正方形圍住 \n from browser import html, document as doc, window # Create canvas element canvas = html.CANVAS(width=500, height=500) # Increase canvas size to ensure circles are fully visible brython_div = doc["brython_div1"] brython_div <= canvas # Get the drawing context of the canvas ctx = canvas.getContext("2d") # Draw the first empty square at (0, 0) width = 10 height = 10 gs = 20 # Grid size (for spacing) ctx.lineWidth = 2 ctx.strokeStyle = \'red\' # Color for the first square ctx.beginPath() ctx.rect(50, 50, width * gs, height * gs) # Draw a hollow square with offset (50, 50) ctx.stroke() # Draw the second empty square at (100, 100) offset_x = 150 # Change the x-coordinate to give more space offset_y = 150 # Change the y-coordinate to give more space width2 = 10 height2 = 10 ctx.lineWidth = 2 ctx.strokeStyle = \'red\' # Color for the second square ctx.beginPath() ctx.rect(offset_x, offset_y, width2 * gs, height2 * gs) # Draw another hollow square ctx.stroke() # Function to draw a circle around a square def draw_outer_circle(x, y, width, height):  # Calculate the radius of the outer circle (half of the diagonal of the square)  radius = window.Math.sqrt(width ** 2 + height ** 2) / 2  # Calculate the center of the square  center_x = x + width * gs / 2  center_y = y + height * gs / 2  # Draw the outer circle  ctx.beginPath()  ctx.arc(center_x, center_y, radius * gs, 0, 2 * window.Math.PI)  ctx.strokeStyle = \'black\' # Color for the outer circle  ctx.lineWidth = 2  ctx.stroke() # Draw outer circles around both squares draw_outer_circle(50, 50, width, height) # For the first square draw_outer_circle(offset_x, offset_y, width2, height2) # For the second square # Create the context menu context_menu = html.DIV(style={"position": "absolute", "display": "none", "background-color": "#fff", "border": "1px solid #ccc", "padding": "5px"}) context_menu <= html.BUTTON("Option 1: Clear Canvas") context_menu <= html.BUTTON("Option 2: Draw Circle") brython_div <= context_menu # Function to show context menu def show_context_menu(event):  event.preventDefault() # Prevent the default right-click menu  context_menu.style.display = "block" # Show custom context menu  context_menu.style.left = f"{event.pageX}px" # Set the position of the menu  context_menu.style.top = f"{event.pageY}px" # Hide the context menu when clicking elsewhere def hide_context_menu(event):  context_menu.style.display = "none" # Attach right-click (contextmenu) event to the canvas canvas.bind("contextmenu", show_context_menu) # Attach click event to document to hide the menu when clicking elsewhere document.bind("click", hide_context_menu) # Function for the menu options def clear_canvas(event):  ctx.clearRect(0, 0, canvas.width, canvas.height) # Clear the canvas  context_menu.style.display = "none" # Hide the context menu after action def draw_circle(event):  ctx.beginPath()  ctx.arc(200, 200, 50, 0, 2 * window.Math.PI) # Draw a circle at the center  ctx.strokeStyle = \'green\'  ctx.stroke()  context_menu.style.display = "none" # Hide the context menu after action # Attach actions to context menu buttons context_menu.children[0].bind("click", clear_canvas) # First button: Clear canvas context_menu.children[1].bind("click", draw_circle) # Second button: Draw a circle \n 圓被正方形圍住並上色 \n from browser import html \n from browser import document as doc \n import math \n canvas = html.CANVAS(width=500, height=500) \n brython_div = doc["brython_div1"] \n brython_div <= canvas \n ctx = canvas.getContext("2d") \n ctx.lineWidth = 4 \n #混色的 \n ctx.globalCompositeOperation = "screem" \n #黑邊圓*2(每個畫四個邊邊) \n ctx.strokeStyle = \'black\' \n #第一個圓 \n ctx.beginPath() \n ctx.arc(160, 160, 141, 0.25 * math.pi,0.75 * math.pi) \n ctx.fillStyle = "Aqua" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(160, 160, 141, 0.75 * math.pi,1.25 * math.pi) \n ctx.fillStyle = "Chartreuse" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(160, 160, 141, 1.25 * math.pi,1.75 * math.pi) \n ctx.fillStyle = "Chocolate" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(160, 160, 141, 1.75 * math.pi,0.25 * math.pi) \n ctx.fillStyle = "FloralWhite" \n ctx.fill() \n ctx.stroke() \n #第二個圓 \n ctx.beginPath() \n ctx.arc(260, 260, 141, 1.25 * math.pi,1.75 * math.pi) \n ctx.fillStyle = "Purple" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(260, 260, 141, 1.75 * math.pi,0.25 * math.pi) \n ctx.fillStyle = "Crimson" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(260, 260, 141, 0.25 * math.pi,0.75 * math.pi) \n ctx.fillStyle = "Orange" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.arc(260, 260, 141, 0.75 * math.pi,1.25 * math.pi) \n ctx.fillStyle = "MediumVioletRed" \n ctx.fill() \n ctx.stroke() \n #紅方形*2(4個三角形) \n ctx.strokeStyle = \'red\' \n ctx.beginPath() \n ctx.moveTo(60,60) \n ctx.lineTo(60,260) \n ctx.lineTo(260,260) \n ctx.fillStyle = "Gold" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.moveTo(60,60) \n ctx.lineTo(260,60) \n ctx.lineTo(260,260) \n ctx.fillStyle = "Indigo" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.moveTo(160,160) \n ctx.lineTo(360,160) \n ctx.lineTo(360,360) \n ctx.fillStyle = "Cyan" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.moveTo(160,160) \n ctx.lineTo(160,360) \n ctx.lineTo(360,360) \n ctx.fillStyle = "Fuchsia" \n ctx.fill() \n ctx.stroke() \n #重疊的小方型 \n ctx.beginPath() \n ctx.moveTo(160,160) \n ctx.lineTo(160,260) \n ctx.lineTo(260,260) \n ctx.fillStyle = "ForestGreen" \n ctx.fill() \n ctx.stroke() \n ctx.beginPath() \n ctx.moveTo(160,160) \n ctx.lineTo(260,160) \n ctx.lineTo(260,260) \n ctx.fillStyle = "SlateBlue" \n ctx.fill() \n ctx.stroke() \n #籃斜線 \n ctx.strokeStyle = \'blue\' \n ctx.beginPath() \n ctx.moveTo(60, 60) \n ctx.lineTo(360, 360) \n ctx.stroke() \n \n', 'tags': '', 'url': 'w13_hw.html'}, {'title': 'w14_ex', 'text': '三個圓形並上色 \n from browser import html from browser import document as doc import random import math \n # 定義一個函式來初始化畫布 def initialize_canvas(canvas_width=400, canvas_height=400, id="brython_div1"):  # 創建 canvas 並設置寬度與高度  canvas = html.CANVAS(width=canvas_width, height=canvas_height)  brython_div = doc[id]  brython_div <= canvas    # 獲取 canvas 的 2D 上下文  ctx = canvas.getContext("2d")    return canvas, ctx \n # 定義一個隨機顏色生成函式 def random_color_generator():  r = random.randint(0, 255)  g = random.randint(0, 255)  b = random.randint(0, 255)  return f"rgb({r}, {g}, {b})" \n # 判斷點 (px, py) 是否在圓內 def is_point_in_circle(px, py, cx, cy, r):  return (px - cx) ** 2 + (py - cy) ** 2 <= r ** 2 \n # 使用者設定的圓心座標和半徑，並進行掃描線填充 def draw_circles(x1, y1, r1, x2, y2, r2, x3, y3, r3):  # 初始化畫布  canvas, ctx = initialize_canvas(400, 400)    # 清除畫布  ctx.clearRect(0, 0, canvas.width, canvas.height)    # 顏色區域存儲  color_dict = {} \n # 使用掃描線方法填充區域  for py in range(0, canvas.height):  # 逐行掃描，判斷每個點是否在圓內  current_color = None # 當前掃描線區域的顏色  for px in range(0, canvas.width):  in_circle1 = is_point_in_circle(px, py, x1, y1, r1)  in_circle2 = is_point_in_circle(px, py, x2, y2, r2)  in_circle3 = is_point_in_circle(px, py, x3, y3, r3)    if in_circle1 and in_circle2 and in_circle3:  # 三個圓的交集區域  if "all_three" not in color_dict:  color_dict["all_three"] = random_color_generator()  current_color = color_dict["all_three"]  elif in_circle1 and in_circle2:  # 圓1與圓2的交集區域  if "circle1_and_2" not in color_dict:  color_dict["circle1_and_2"] = random_color_generator()  current_color = color_dict["circle1_and_2"]  elif in_circle2 and in_circle3:  # 圓2與圓3的交集區域  if "circle2_and_3" not in color_dict:  color_dict["circle2_and_3"] = random_color_generator()  current_color = color_dict["circle2_and_3"]  elif in_circle1 and in_circle3:  # 圓1與圓3的交集區域  if "circle1_and_3" not in color_dict:  color_dict["circle1_and_3"] = random_color_generator()  current_color = color_dict["circle1_and_3"]  elif in_circle1:  # 只在圓1內  if "circle1" not in color_dict:  color_dict["circle1"] = random_color_generator()  current_color = color_dict["circle1"]  elif in_circle2:  # 只在圓2內  if "circle2" not in color_dict:  color_dict["circle2"] = random_color_generator()  current_color = color_dict["circle2"]  elif in_circle3:  # 只在圓3內  if "circle3" not in color_dict:  color_dict["circle3"] = random_color_generator()  current_color = color_dict["circle3"]  else:  # 點不在三個圓內，畫外區域  current_color = "white" # 背景色白色 \n # 填充顏色  ctx.fillStyle = current_color  ctx.fillRect(px, py, 1, 1) # 填充一個像素 \n # 直接設定三個圓心和半徑 x1, y1, r1 = 150, 200, 100 # 圓1：圓心 (150, 200)，半徑 100 x2, y2, r2 = 250, 200, 100 # 圓2：圓心 (250, 200)，半徑 100 x3, y3, r3 = 200, 100, 100 # 圓3：圓心 (200, 100)，半徑 100 \n # 呼叫畫圓函式 draw_circles(x1, y1, r1, x2, y2, r2, x3, y3, r3) \n', 'tags': '', 'url': 'w14_ex.html'}, {'title': 'w16_exam1', 'text': 'from browser import document, html\nimport math\n \n# 初始化 HTML，確保 canvas 元素存在\ndef setup_canvas():\n    if not document.querySelector("#my_canvas"):\n        canvas = html.CANVAS(id="my_canvas", width=800, height=600)\n        document <= canvas\n \nsetup_canvas()\n\n# Set up canvas\ncanvas = document["my_canvas"]\nctx = canvas.getContext("2d")\n\n# Set origin (32, 11)\norigin_x, origin_y = 32, 11    #自己學號 修改\n\n# Draw X-axis\nctx.beginPath()\nctx.moveTo(origin_x, origin_y)\nctx.lineTo(500, origin_y)\nctx.strokeStyle = "black"\nctx.lineWidth = 2\nctx.stroke()\n\n# Draw Y-axis\nctx.beginPath()\nctx.moveTo(origin_x, origin_y)\nctx.lineTo(origin_x, 300)\nctx.stroke()\n\n# Label origin\nctx.font = "12px Arial"\nctx.fillStyle = "black"\nctx.fillText("(32, 11)", origin_x + 5, origin_y - 5)\n\n# Draw shapes\n# Adjusted placement to fix alignment issue\n\n# Hexagon (Orange)\nhex_x, hex_y = 100, 100\nctx.beginPath()\nfor i in range(6):\n    angle = i * (2 * math.pi / 6)\n    x = hex_x + 30 * math.cos(angle)\n    y = hex_y + 30 * math.sin(angle)\n    if i == 0:\n        ctx.moveTo(x, y)\n    else:\n        ctx.lineTo(x, y)\nctx.closePath()\nctx.fillStyle = "orange"\nctx.fill()\n\n# Diamond (Teal)\nctx.beginPath()\nctx.moveTo(160, 70)\nctx.lineTo(180, 100)\nctx.lineTo(160, 130)\nctx.lineTo(140, 100)\nctx.closePath()\nctx.fillStyle = "teal"\nctx.fill()\n\n# Triangle (Teal)\nctx.beginPath()\nctx.moveTo(165, 130)\nctx.lineTo(205, 130)\nctx.lineTo(185, 100)\nctx.closePath()\nctx.fillStyle = "blue"\nctx.fill()\n\n# Circle (Pink)\nctx.beginPath()\nctx.arc(230, 100, 30, 0, 2 * math.pi)\nctx.fillStyle = "pink"\nctx.fill()\n\n# Square (Yellow)\nctx.beginPath()\nctx.rect(265, 75, 50, 50)\nctx.fillStyle = "yellow"\nctx.fill()\n\n# Rectangle (Blue)\nctx.beginPath()\nctx.rect(320, 90, 60, 20)\nctx.fillStyle = "Blue"\nctx.fill() \n', 'tags': '', 'url': 'w16_exam1.html'}, {'title': 'HW 1 Exam', 'text': '', 'tags': '', 'url': 'HW 1 Exam.html'}, {'title': 'w7-1', 'text': '1.在作業網站叫出Brython \n \n \n', 'tags': '', 'url': 'w7-1.html'}, {'title': 'HW 2', 'text': '主題: Python 的數列、判斷式與重複迴圈 (20%) \n Python 課程教材:  https://www.learnpythonwithjupyter.com/  - PART 2 and Part 3 \n \n 延續 HW 1 網頁資料整理與程式練習方法, 整理下列內容 (20%): \n PART 2: Introduction to lists and if/else statements \n PART 3: Introduction to the for loop \n 完成上述流程整理後, 請將 HW2 自評分數輸入 cp2024 自評表單中. \n', 'tags': '', 'url': 'HW 2.html'}, {'title': 'w7-2', 'text': '', 'tags': '', 'url': 'w7-2.html'}, {'title': 'HW 2 Exam', 'text': '每六人為一組進行協同程式練習 \n 透過 Jupyterlab 協同網頁, 輪流指定各組編寫 HW 2 相關的程式練習, 以及網頁內容 (localhost 與 Codespaces 環境)編輯. \n', 'tags': '', 'url': 'HW 2 Exam.html'}, {'title': 'W5', 'text': '#單行註解 #help(print) \'\'\'這個三引號所界定\'的區域被Python視為多行註解\'\'\' a = "一個字串" a = 24 a = 24.5 print(a) b = print(a, a, a, sep=\'*\') print(b) \n def print_star_shape(rows):  for i in range(rows):  # 印出空格  print(\' \' * (rows - i - 1), end=\'\')  # 印出星星  print(\'* \' * (i + 1)) \n # 設定三角形的行數 rows = 30 print_star_shape(rows) \n #help(range) for i in range(1, 6, 2):  print(i, end="")   print() def print_centered_star_pyramid(n):  for i in range(n):  # 印出多兩個空格以對齊星星  spaces = \' \' * (n - i - 1)  stars = \'*\' * (2 * i + 1)  print(spaces + stars) \n # 調用函數，設定金字塔的高度 height = 20 print_centered_star_pyramid(height) \n \n \n', 'tags': '', 'url': 'W5.html'}, {'title': 'W6', 'text': '操作步驟: \n \n 下載 python_2025_lite.7z（可攜程式環境） \n 下載 zmq_remote_api ex cube_triangle.7z（税用 Python 控制模擬場景中的物件） \n 進入可攜程式環境中 data/CoppeliaSim 目錄，開啟 coppeliasim.exe（機電整合模擬程式，原始碼） \n 啟動可攜程式環境，雙點擊 start_ipv6.bat，系統會啟動四個命令列，兩個 SciTE 編輯器 \n 執行場景控制程式前，先處理操作系統的防火牆，將下列指令存為，bat 檔案後，以管理員身袋執行，以便開啟 23000-23050 號進出： \n netsh advfirewall firewall add rule name="allow _23000-23050™ dir=in action=allow protocol=TCP localport=23000-23050 netsh advfirewall firewall add rule name="allow_23000-23050" dir=out action=allow protocol=TCP localport=23000-23050\xa0 \n 開啟 CoppeliaSim 中的視覺串流伺服器：Modules - Connectivity - Visualization stream\xa0 \n 利用 SCITE 開啟 put_cubes_into_scene__1.py， 利用 Tools -Go 執行操控程式 \n 使用者可以透過瀏覽器,以模擬場景所在電腦的IP,且埠號為23020 觀看模擬場景。 \n \n \n 程式碼 :from coppeliasim_zmqremoteapi_client import RemoteAPIClient import time import keyboard \n # 利用 zmqRemoteAPI 以 23000 對場景伺服器進行連線 client = RemoteAPIClient(\'[::1]\', 23000) # 以 getObject 方法取得場景物件 sim = client.getObject(\'sim\') box = sim.getObject(\'/box\') \n # 啟動模擬 sim.startSimulation() \n # 設定立方體的尺寸和初始位置 cube_size = 0.2 # 20 cm spacing = 0.5 # 50 cm 之間的距離（可根據需求調整） \n # 擺放立方體的行數和每行的數量 rows = 5 # 從第 1 行到第 5 行 cubes_in_row = [1, 3, 5, 7, 9] # 每行立方體的數量 \n # 在正的 Y 方向擺放立方體 for row in range(rows):  # 計算每行的起始 x 位置，讓其對稱  start_row_x = - (cubes_in_row[row] - 1) * spacing / 2    for col in range(cubes_in_row[row]):  # 計算每個立方體的位置  x_position = start_row_x + col * spacing  y_position = row * spacing # 垂直方向上每行間距    # 建立立方體  cube_handle = sim.createPrimitiveShape(sim.primitiveshape_cuboid, [cube_size, cube_size, cube_size], 0)  sim.setObjectPosition(cube_handle, -1, [x_position, y_position, cube_size / 2]) # z 方向上升到立方體的中心 \n # 在負的 Y 方向擺放立方體 for row in range(rows):  # 計算每行的起始 x 位置，讓其對稱  start_row_x = - (cubes_in_row[row] - 1) * spacing / 2    for col in range(cubes_in_row[row]):  # 計算每個立方體的位置  x_position = start_row_x + col * spacing  y_position = -row * spacing # 負的 Y 方向    # 建立立方體  cube_handle = sim.createPrimitiveShape(sim.primitiveshape_cuboid, [cube_size, cube_size, cube_size], 0)  sim.setObjectPosition(cube_handle, -1, [x_position, y_position, cube_size / 2]) # z 方向上升到立方體的中心 \n # 完成立方體的擺放 print("立方體已成功擺放!") \n # 設定主迴圈 while True:  # 在這裡可以進行其他模擬操作  time.sleep(0.1) # 確保循環不會過快 \n if keyboard.is_pressed(\'q\'):  # 可以按下 q 鍵跳出重複執行迴圈  break \n # 終止模擬 sim.stopSimulation() \n \n \n', 'tags': '', 'url': 'W6.html'}, {'title': 'HW 3 Exam', 'text': '每六人為一組進行協同程式練習 \n 透過 Jupyterlab 協同網頁, 輪流指定各組編寫 HW 3 相關的程式練習, 以及網頁內容 (localhost 與 Codespaces 環境)編輯. \n', 'tags': '', 'url': 'HW 3 Exam.html'}, {'title': 'HW 4', 'text': '主題: 利用 Python 控制機電模擬系統 (20%) \n 利用\xa0 https://solvespace.com/ \xa0建立機械系統零組件 \n 利用  CoppeliaSim  建立機電模擬系統 \n 利用  Python  跨網路控制瀏覽器上的機電模擬系統 \n 範例: \n cd2023_pj3ag4_zmq_football_4.7.7z \n cd2024_2b_g6_steel_ball_platform_nxopen_copsim.7z \n 完成上述流程整理後, 請將 HW4 自評分數輸入 cp2024 自評表單中. \n', 'tags': '', 'url': 'HW 4.html'}, {'title': 'HW 4 Exam', 'text': '每六人為一組進行協同程式練習 \n 透過 Jupyterlab 協同網頁, 輪流指定各組編寫 HW 4 相關的程式練習, 以及網頁內容 (localhost 與 Codespaces 環境)編輯. \n', 'tags': '', 'url': 'HW 4 Exam.html'}, {'title': 'Final Report', 'text': "期末口頭與書面專題報告 (20%) \n 期末口頭專題報告影片: \n ...... \n 期末書面專題報告檔案 (pdf): \n ...... \n 電腦輔助設計與實習課程總結心得: \n ...... \n 期末報告自評成績: \n 完成上述流程後, 請將 Final Report 自評分數輸入 cp2024 自評表單中. \n ' \n", 'tags': '', 'url': 'Final Report.html'}, {'title': 'Brython', 'text': '從 1 累加到 100: \n 1 add to 100 \n  導入 brython 程式庫  \n \n \n \n \n  啟動 Brython  \n \n \n \n  導入 FileSaver 與 filereader  \n \n \n \n \n  導入 ace  \n \n \n \n \n \n \n  導入 gearUtils-0.9.js Cango 齒輪繪圖程式庫  \n \n \n \n \n \n \n  請注意, 這裡使用 Javascript 將 localStorage["kw_py_src1"] 中存在近端瀏覽器的程式碼, 由使用者決定存檔名稱 \n \n \n \n \n \n \n  add 1 to 100 開始  \n \n \n  add 1 to 100 結束 \n  editor1 開始  \n  用來顯示程式碼的 editor 區域  \n \n  以下的表單與按鈕與前面的 Javascript doSave 函式以及 FileSaver.min.js 互相配合  \n  存擋表單開始  \n Filename:  .py   \n  存擋表單結束  \n \n  執行與清除按鈕開始  \n Run   Output   清除輸出區 清除繪圖區 Reload \n  執行與清除按鈕結束  \n \n  程式執行 ouput 區  \n \n  Brython 程式執行的結果, 都以 brython_div1 作為切入位置  \n \n  editor1 結束   ##########################################  \n 從 1 累加到 100 part2: \n 1 add to 100 cango_three_gears BSnake AI Tetris Rotating Block \n  請注意, 這裡使用 Javascript 將 localStorage["kw_py_src2"] 中存在近端瀏覽器的程式碼, 由使用者決定存檔名稱 \n \n \n \n  add 1 to 100 part2 開始  \n \n \n  add 1 to 100 part2 結束 \n  editor2 開始  \n  用來顯示程式碼的 editor 區域  \n \n  以下的表單與按鈕與前面的 Javascript doSave 函式以及 FileSaver.min.js 互相配合  \n  存擋表單開始  \n Filename:  .py   \n  存擋表單結束  \n \n  執行與清除按鈕開始  \n Run   Output   清除輸出區 清除繪圖區 Reload \n  執行與清除按鈕結束  \n \n  程式執行 ouput 區  \n \n  Brython 程式執行的結果, 都以 brython_div1 作為切入位置  \n \n  editor2 結束  \n \n \n', 'tags': '', 'url': 'Brython.html'}]};